package com.nexusdrive.storage.service;import com.nexusdrive.common.exception.ResourceNotFoundException;import com.nexusdrive.storage.config.StorageProperties;import jakarta.annotation.PostConstruct;import java.io.*;import java.nio.file.*;import org.springframework.stereotype.Service;@Service public class ChunkStorageService{private final Path root;public ChunkStorageService(StorageProperties p){root=p.getPath().toAbsolutePath().normalize();}@PostConstruct void init()throws IOException{Files.createDirectories(root);}public void put(String id,byte[] data){Path target=resolve(id);try{Path tmp=Files.createTempFile(root,"chunk-",".tmp");Files.write(tmp,data,StandardOpenOption.TRUNCATE_EXISTING);try{Files.move(tmp,target,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){Files.move(tmp,target,StandardCopyOption.REPLACE_EXISTING);}}catch(IOException e){throw new UncheckedIOException(e);}}public byte[] get(String id){try{return Files.readAllBytes(resolve(id));}catch(NoSuchFileException e){throw new ResourceNotFoundException("Chunk not found");}catch(IOException e){throw new UncheckedIOException(e);}}public void delete(String id){try{Files.deleteIfExists(resolve(id));}catch(IOException e){throw new UncheckedIOException(e);}}private Path resolve(String id){if(!id.matches("[A-Za-z0-9_-]{1,200}"))throw new IllegalArgumentException("Invalid chunk id");Path p=root.resolve(id+".chunk").normalize();if(!p.startsWith(root))throw new IllegalArgumentException("Invalid chunk id");return p;}}
